script:
(function () {
  const sel = '.so-hz .form-column .frappe-control:not([data-fieldtype="Check"]):not([data-fieldtype="Table"]):not([data-fieldtype="Button"]):not([data-fieldtype="HTML"]) .form-group';
  [['si-fluid-style', `
.so-hz .form-column{container-type:inline-size;container-name:fcol}
${sel}>.clearfix{flex:0 0 clamp(110px,32%,190px);max-width:none}
.so-hz .form-column .frappe-control[data-fieldtype="Check"] > .checkbox{margin-left:calc(clamp(110px,32%,190px) + 8px)}
@container fcol (max-width:400px){
  ${sel}{flex-direction:column;gap:0}
  ${sel}>.clearfix{flex:none;width:100%;padding-top:0}
  .so-hz .form-column .frappe-control[data-fieldtype="Check"] > .checkbox{margin-left:0}
}
.so-hz .form-column .frappe-control .control-input-wrapper,.so-hz .form-column .frappe-control .control-input{max-width:100%}
.so-hz .frappe-control[data-fieldtype="Table"]{container-type:inline-size;container-name:gridc}
@container gridc (min-width:900px){
  .so-hz .column-limit-reached .form-grid .grid-static-col:not(:nth-child(-n+2)):not(:last-child){min-width:0;width:auto;flex:1 1 0}
  .so-hz .column-limit-reached .form-grid .grid-static-col.col-xs-2:not(:nth-child(-n+2)):not(:last-child){flex-grow:2}
  .so-hz .column-limit-reached .form-grid .grid-static-col.col-xs-3:not(:nth-child(-n+2)):not(:last-child){flex-grow:3}
  .so-hz .column-limit-reached .form-grid .grid-static-col.col-xs-4:not(:nth-child(-n+2)):not(:last-child){flex-grow:4}
  .so-hz .column-limit-reached .form-grid .grid-heading-row .grid-static-col{height:auto;min-height:32px}

.so-hz .form-grid .grid-heading-row .static-area,.so-hz .form-grid .grid-heading-row .grid-static-col:not(.row-index){white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.so-hz .form-grid .row-index{flex:0 0 44px !important;min-width:44px !important;width:44px !important;max-width:44px !important;overflow:visible !important;text-overflow:clip !important;padding-left:0 !important;padding-right:0 !important;text-align:center}
.so-hz .form-grid .row-index span{display:inline-block;white-space:nowrap;overflow:visible}
.so-hz .form-grid [data-fieldname="custom_discount_type"]{min-width:110px}
.so-hz .form-grid [data-fieldname="custom_discount_value"],.so-hz .form-grid [data-fieldname="qty"],.so-hz .form-grid [data-fieldname="delivered_qty"],.so-hz .form-grid [data-fieldname="custom_invoiced_qty"]{min-width:80px}
`], ['si-hz-style', `
${sel}{display:flex;flex-direction:row;align-items:flex-start;gap:8px;margin-bottom:4px}
${sel}>.clearfix{flex:0 0 32%;max-width:32%;margin:0;padding-top:4px}
${sel}>.control-input-wrapper,${sel}>.control-input,${sel}>.control-value{flex:1 1 auto;min-width:0}
.so-hz .form-column .frappe-control[data-fieldtype="Check"] > .checkbox{margin-left:calc(32% + 8px);margin-bottom:4px}
.so-hz .form-column .frappe-control .help-box{display:none !important}

.so-hz [data-fieldname="posting_date"] .control-input-wrapper,
.so-hz [data-fieldname="custom_accounting_date"] .control-input-wrapper,
.so-hz [data-fieldname="due_date"] .control-input-wrapper,
.so-hz [data-fieldname="currency"] .control-input-wrapper,
.so-hz [data-fieldname="custom_otobitz_branch"] .control-input-wrapper,
.so-hz [data-fieldname="custom_sale_order_date"] .control-input-wrapper,
.so-hz [data-fieldname="payment_terms_template"] .control-input-wrapper,
.so-hz [data-fieldname="custom_discount_applies_to"] .control-input-wrapper,
.so-hz [data-fieldname="custom_otobitz_vehicle"] .control-input-wrapper,
.so-hz [data-fieldname="custom_tahun_kendaraan"] .control-input-wrapper,
/* ponytail: short-value fields (IDs, phone, dates, codes) get 220px like the date fields; email, address, names and references keep the full column. */
.so-hz [data-fieldname="tax_id"] .control-input-wrapper,
.so-hz [data-fieldname="custom_nik"] .control-input-wrapper,
.so-hz [data-fieldname="custom_phone"] .control-input-wrapper,
.so-hz [data-fieldname="out_fp_no"] .control-input-wrapper,
.so-hz [data-fieldname="out_fp_date"] .control-input-wrapper,
.so-hz [data-fieldname="custom_tax_number"] .control-input-wrapper,
.so-hz [data-fieldname="incoterm"] .control-input-wrapper,
.so-hz [data-fieldname="tax_category"] .control-input-wrapper,
.so-hz [data-fieldname="custom_odometer"] .control-input-wrapper{max-width:220px !important}

/* si-fit */
.so-hz [data-fieldname="items"] .form-grid{grid-template-columns:minmax(0,1fr) !important;overflow-x:auto !important}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row,.so-hz [data-fieldname="items"] .form-grid .grid-body{min-width:930px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="item_code"]{box-sizing:border-box !important;flex:2 1 76px !important;min-width:76px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="description"]{box-sizing:border-box !important;flex:1.5 1 52px !important;min-width:52px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="income_account"]{box-sizing:border-box !important;flex:1.5 1 72px !important;min-width:72px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="cost_center"]{box-sizing:border-box !important;flex:1.2 1 46px !important;min-width:46px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="custom_analytic_tags"]{box-sizing:border-box !important;flex:0.8 1 36px !important;min-width:36px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="custom_discount_type"]{box-sizing:border-box !important;flex:1.4 1 72px !important;min-width:72px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="custom_discount_value"]{box-sizing:border-box !important;flex:1.8 1 70px !important;min-width:70px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="qty"]{box-sizing:border-box !important;flex:0.8 1 34px !important;min-width:34px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="uom"]{box-sizing:border-box !important;flex:1.2 1 52px !important;min-width:52px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="price_list_rate"]{box-sizing:border-box !important;flex:1.7 1 88px !important;min-width:88px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="item_tax_template"]{box-sizing:border-box !important;flex:1.5 1 76px !important;min-width:76px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="net_amount"]{box-sizing:border-box !important;flex:1.7 1 88px !important;min-width:88px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="amount"]{box-sizing:border-box !important;flex:1.7 1 88px !important;min-width:88px !important;width:auto !important;max-width:none !important}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col{padding-left:6px !important;padding-right:6px !important}
/* si-head-wrap */
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .static-area,.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col{white-space:normal !important;line-height:1.25;text-overflow:clip !important}
.so-hz [data-fieldname="items"] .form-grid .grid-body .grid-static-col .static-area{font-size:12px}

/* Badge pill hijau persis Odoo untuk kolom Tax di Order Lines */
.grid-body .grid-row [data-fieldname="item_tax_template"] .static-area {
    display: inline-block;
    background: #e6f4ea !important;
    color: #137333 !important;
    font-size: 11px !important;
    font-weight: 500 !important;
    padding: 2px 8px !important;
    border-radius: 12px !important;
}
`], ['si-totals-style', `
.so-tot{margin-left:auto;max-width:420px;background:#dbe4ef;border-radius:8px;padding:12px 16px}
.so-tot-row{display:flex;justify-content:space-between;gap:16px;padding:5px 0;font-size:13px;color:var(--text-color)}
.so-tot-row b{color:var(--text-color);font-weight:500}
.so-tot-row.grand{border-top:1px solid #b6c4d6;margin-top:6px;padding-top:10px;font-size:15px;color:var(--text-color);font-weight:700}
.so-tot-row.grand b{font-weight:700}
.so-tot-row.grand.due{border-top:1px solid #b6c4d6;margin-top:4px;padding-top:8px}
.so-hz .form-grid .grid-heading-row,.so-hz .form-grid .grid-heading-row .grid-row,.so-hz .form-grid .grid-heading-row .data-row,.so-hz .form-grid .grid-heading-row .grid-static-col,.so-hz .form-grid .grid-heading-row .row-check,.so-hz .form-grid .grid-heading-row .row-index{background-color:#dbe4ef !important}
`], ['si-prop', `
/* si-prop */
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="item_code"]{flex:1.8 1 72px !important;min-width:72px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="description"]{flex:1.2 1 56px !important;min-width:56px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="income_account"]{flex:1.3 1 68px !important;min-width:68px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="cost_center"]{flex:0.9 1 60px !important;min-width:60px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="custom_analytic_tags"]{flex:0.8 1 64px !important;min-width:64px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="custom_discount_type"]{flex:1 1 76px !important;min-width:76px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="custom_discount_value"]{flex:1 1 62px !important;min-width:62px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="qty"]{flex:0.6 1 58px !important;min-width:58px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="uom"]{flex:0.7 1 44px !important;min-width:44px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="price_list_rate"]{flex:1.2 1 78px !important;min-width:78px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="item_tax_template"]{flex:1 1 68px !important;min-width:68px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="net_amount"]{flex:1.3 1 90px !important;min-width:90px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col[data-fieldname="amount"]{flex:1.3 1 90px !important;min-width:90px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-static-col{padding-left:4px !important;padding-right:4px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row,.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .data-row,.so-hz [data-fieldname="items"] .form-grid .grid-heading-row>.row{height:auto !important;min-height:34px}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col{height:auto !important;display:flex;align-items:center;padding-top:6px;padding-bottom:6px}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .static-area{overflow:visible !important;white-space:normal !important;line-height:1.2;text-overflow:clip !important;font-size:11px !important}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col[data-fieldname="qty"]{justify-content:flex-end;text-align:right}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col[data-fieldname="custom_discount_value"]{justify-content:flex-end;text-align:right}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col[data-fieldname="price_list_rate"]{justify-content:flex-end;text-align:right}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col[data-fieldname="net_amount"]{justify-content:flex-end;text-align:right}
.so-hz [data-fieldname="items"] .form-grid .grid-heading-row .grid-static-col[data-fieldname="amount"]{justify-content:flex-end;text-align:right}
`]].forEach(([id, css]) => {
    if (document.getElementById(id)) return;
    const s = document.createElement('style'); s.id = id; s.textContent = css; document.head.appendChild(s);
  });
})();
$(document.body).addClass('full-width'); localStorage.container_fullwidth = 'true';

const SI_INC_TAX = '(Inc) Pajak Pertambahan Nilai - PAO';
frappe.ui.form.on('Sales Invoice', {
  setup(frm) {
    frm.set_query('custom_otobitz_vehicle', () => ({
      query: 'otobitz_integration.otobitz_integration.doctype.otobitz_vehicle.otobitz_vehicle.search_vehicle', filters: {}
    }));
  },
  onload(frm) {
    if (!frm.is_new()) return;
    if (!frm.doc.custom_salesperson) frm.set_value('custom_salesperson', frappe.session.user);
    if (!frm.doc.custom_accounting_date) frm.set_value('custom_accounting_date', frappe.datetime.get_today());
  },
  refresh(frm) {
    $(frm.wrapper).addClass('so-hz'); $(document.body).addClass('full-width');
    frm.set_query('uom', 'items', () => ({filters: {name: ['in', ['Units', 'Dozen']]}}));
    // ponytail: erpnext.hide_company hides Company with one company; re-show after it runs
    setTimeout(() => frm.toggle_display('company', true), 300);
    // ponytail: Frappe re-shows naming_series on new docs; Odoo has no Series field. Default ACC-SINV-.YYYY.- is set by Property Setter.
    setTimeout(() => frm.toggle_display('naming_series', false), 300);
    // ponytail: imogi_finance locks out_fp_* read-only (Frappe hides empty read-only fields) and ERPNext hides net_amount until discount/inclusive tax; Odoo always shows both. eFaktur data comes from the Odoo API, so unlock.
    setTimeout(() => {
      ['out_fp_no', 'out_fp_date', 'out_fp_tax_invoice_pdf'].forEach(f => frm.set_df_property(f, 'read_only', 0));
      const g = frm.fields_dict.items.grid;
      g.set_column_disp('net_amount', true);
      si_toggle_disc(frm);
    }, 500);
    // si-from-so: invoice created from SO via mapper -> link header Sale Order (triggers vehicle fill)
    if (frm.is_new() && !frm.doc.custom_sale_order) {
      const r = (frm.doc.items || []).find(i => i.sales_order);
      if (r) frm.set_value('custom_sale_order', r.sales_order);
    }
    si_toggle_disc(frm);
    frm._si_tot_key = null; si_render_totals(frm);
    // ponytail: poll because ERPNext sets totals without field events; swap for a calculate_taxes_and_totals hook if heavy
    clearInterval(frm._si_tot_t);
    frm._si_tot_t = setInterval(() => { if (cur_frm !== frm) return clearInterval(frm._si_tot_t); si_render_totals(frm); }, 400);
  },
  custom_discount_applies_to(frm) { si_toggle_disc(frm); },
  // Odoo copies vehicle data from the Sale Order; fields are read-only here
  custom_sale_order(frm) {
    const so = frm.doc.custom_sale_order;
    if (!so) { frm.set_value({custom_sale_order_date: '', custom_otobitz_vehicle: '', custom_tahun_kendaraan: '', custom_odometer: 0, custom_otobitz_teknisi: ''}); return; }
    frappe.db.get_value('Sales Order', so, ['customer', 'transaction_date', 'custom_otobitz_vehicle', 'custom_tahun_kendaraan', 'custom_odometer', 'custom_otobitz_teknisi', 'custom_saran', 'custom_discount_applies_to'], r => {
      if (!r) return;
      const v = {
        custom_sale_order_date: r.transaction_date, custom_otobitz_vehicle: r.custom_otobitz_vehicle || '',
        custom_tahun_kendaraan: r.custom_tahun_kendaraan || '', custom_odometer: r.custom_odometer || 0,
        custom_otobitz_teknisi: r.custom_otobitz_teknisi || ''
      };
      if (!frm.doc.customer && r.customer) v.customer = r.customer;
      if (!frm.doc.custom_saran && r.custom_saran) v.custom_saran = r.custom_saran;
      if (r.custom_discount_applies_to) v.custom_discount_applies_to = r.custom_discount_applies_to;
      frm.set_value(v);
    });
  },
  custom_salesperson(frm) {
    if (!frm.doc.custom_salesperson) { frm.set_value({custom_oi_employee: '', custom_oi_department: ''}); return; }
    frappe.db.get_value('Employee', {user_id: frm.doc.custom_salesperson}, ['name', 'department']).then(r => {
      const v = r.message || {};
      frm.set_value({custom_oi_employee: v.name || '', custom_oi_department: v.department || ''});
    });
  },
  custom_oi_employee(frm) {
    if (!frm.doc.custom_oi_employee) return;
    frappe.db.get_value('Employee', frm.doc.custom_oi_employee, 'department').then(r => frm.set_value('custom_oi_department', (r.message || {}).department || ''));
  },
  custom_otobitz_vehicle(frm) {
    if (!frm.doc.custom_otobitz_vehicle) { frm.set_value('custom_tahun_kendaraan', ''); return; }
    frappe.db.get_value('OtoBitz Vehicle', frm.doc.custom_otobitz_vehicle, ['tahunpembuatan', 'last_odometer', 'customer'], r => {
      if (!r) return;
      frm.set_value('custom_tahun_kendaraan', r.tahunpembuatan || '');
      if (r.last_odometer) frm.set_value('custom_odometer', r.last_odometer);
      if (r.customer) frm.set_value('customer', r.customer);
    });
  }
});

function si_apply_discount(frm, cdt, cdn) {
  const r = locals[cdt][cdn];
  const v = flt(r.custom_discount_value);
  const pct = (r.custom_discount_type === 'Percentage');
  r[pct ? 'discount_amount' : 'discount_percentage'] = 0;
  r[pct ? 'discount_percentage' : 'discount_amount'] = v;
  frm.script_manager.trigger(pct ? 'discount_percentage' : 'discount_amount', cdt, cdn);
  frm.refresh_field('items');
}
frappe.ui.form.on('Sales Invoice Item', {
  custom_discount_type(frm, cdt, cdn) { si_apply_discount(frm, cdt, cdn); },
  custom_discount_value(frm, cdt, cdn) { si_apply_discount(frm, cdt, cdn); },
  items_add(frm, cdt, cdn) {
    frappe.model.set_value(cdt, cdn, 'custom_discount_type', 'Fixed');
    frappe.model.set_value(cdt, cdn, 'item_tax_template', SI_INC_TAX);
  },
  item_code(frm, cdt, cdn) {
    frappe.after_ajax(() => {
      const r = locals[cdt][cdn];
      if (r && r.item_code && !r.item_tax_template) frappe.model.set_value(cdt, cdn, 'item_tax_template', SI_INC_TAX);
    });
  }
});

function si_render_totals(frm) {
  const f = frm.fields_dict.custom_totals_html;
  if (!f) return;
  const d = frm.doc, fmt = v => format_currency(flt(v), d.currency);
  const disc = (d.items || []).reduce((a, r) => a + flt(r.discount_amount) * flt(r.qty), 0);
  const tax = (d.taxes || [])[0];
  const lbl = tax ? 'PPN ' + (flt(tax.rate) % 1 ? flt(tax.rate, 2) : parseInt(tax.rate)) + '%' : 'PPN';
  const key = [disc, d.net_total, d.total_taxes_and_charges, d.grand_total, lbl].join('|') + '|' + d.docstatus + '|' + d.outstanding_amount;
  if (frm._si_tot_key === key) return;
  frm._si_tot_key = key;
  f.$wrapper.html(`<div class="so-tot">
    <div class="so-tot-row"><span>Line Discount</span><b>${fmt(disc)}</b></div>
    <div class="so-tot-row"><span>Untaxed Amount</span><b>${fmt(d.net_total)}</b></div>
    <div class="so-tot-row"><span>${lbl}</span><b>${fmt(d.total_taxes_and_charges)}</b></div>
    <div class="so-tot-row grand"><span>Total</span><b>${fmt(d.grand_total)}</b></div>
    <div class="so-tot-row grand due"><span>Amount Due</span><b>${fmt(d.docstatus === 1 ? d.outstanding_amount : d.grand_total)}</b></div></div>`);
}

function si_toggle_disc(frm) {
  // Odoo: Discount Type/Amount columns only when Discount Applies to = Order Line
  const g = frm.fields_dict.items.grid, on = frm.doc.custom_discount_applies_to === 'Order Line';
  g.set_column_disp(['custom_discount_type', 'custom_discount_value'], on);
  g.set_column_disp('net_amount', true);
  g.visible_columns = []; g.reset_grid(); // rebuild rows so cells follow header order
}

/* hide-side */
// ponytail: Odoo has no sidebar; saved docs show it and squeeze grid. Re-enable by deleting this block.
frappe.ui.form.on('Sales Invoice', {
  refresh(frm) {
    frm.page.wrapper.find('.layout-side-section').hide();
    frm.page.wrapper.find('.layout-main-section-wrapper').css({'width': '100%', 'max-width': '100%', 'flex': '0 0 100%'});
  }
});

/* si-num-fmt */
// ponytail: display-only grid shortening for Sales Invoice Item. Account shows code only. Drops "Rp", ",00", extra 3rd decimal zeros, " - PAO" company suffix, "Pajak Pertambahan Nilai" -> "PPN". Only visible text between tags is touched (data-name/href stay intact). Values and DB untouched.
(function () {
  const F = frappe.form.formatters, NUM = ['price_list_rate', 'net_amount', 'amount', 'custom_discount_value'], TXT = ['income_account', 'cost_center', 'item_tax_template'];
  const vis = (html, fn) => html.replace(/>([^<]+)</g, (m, t) => '>' + fn(t) + '<');
