// Odoo-style list: Number first, header #dbe4ef, workflow state pill. ponytail: nth-child tied to column order; update indexes if columns change.
frappe.listview_settings["Purchase Order"].add_fields = ["transaction_date", "workflow_state", "docstatus"];
frappe.listview_settings["Purchase Order"].get_indicator = function (doc) {
  const m = {"Draft": "grey", "Pending Approval": "orange", "Approved": "green", "Rejected": "red"};
  const s = doc.docstatus === 2 ? "Cancelled" : (doc.workflow_state || "Draft");
  return [s, doc.docstatus === 2 ? "red" : (m[s] || "grey"), "workflow_state,=," + (doc.workflow_state || "Draft")];
};
(function () {
  if (document.getElementById("po-list-style")) return;
  const R = '[data-page-route="List/Purchase Order/List"] ', st = document.createElement("style"); st.id = "po-list-style";
  st.textContent =
    R + '.list-row-head,' + R + '.list-row-head .list-row-col,' + R + '.list-row-head .level-item,' + R + '.list-row-head .level-right{background-color:#dbe4ef !important}' +
    R + '.list-row-head{min-height:40px !important;align-items:center !important}' +
    R + '.list-row-col .indicator-pill.grey{background-color:#dbe4ef !important}' +
    R + '.list-row-container .list-row > .level-right,' + R + '.list-row-head > .level-right{display:none !important}' +
    R + '.list-row-container .list-row > .level-left,' + R + '.list-row-head > .level-left{flex:1 1 auto !important;width:100% !important}' +
    R + '.list-row-container .list-row .list-row-col:not(.list-subject):not(.tag-col){flex:1 1 0 !important;min-width:0 !important;width:auto !important}' +
    R + '.list-row .list-subject.level,' + R + '.list-row-head .list-subject.level{min-width:200px !important;width:200px !important;flex:0 0 200px !important}' +
    R + '.list-row-container .list-row .list-subject a{font-weight:600 !important}';
  document.head.appendChild(st);
  const fix = () => document.querySelectorAll(R + '.list-row-head .list-subject span').forEach(e => { if (!e.children.length && e.textContent.trim() === 'ID') e.textContent = 'Number'; });
  new MutationObserver(fix).observe(document.body, {childList: true, subtree: true});
})();

frappe.listview_settings["Sales Invoice"] = {
  add_fields: ["name", "customer", "custom_pph_amount", "customer_name", "posting_date", "due_date", "outstanding_amount", "grand_total", "currency", "status", "docstatus", "is_return"],

  // Odoo list: Number first, credit notes stay out of this menu.
  // ponytail: Frappe has one badge column. Status (Draft/Posted/Cancelled) uses it; Payment Status is drawn by a formatter on outstanding_amount. Odoo "In Payment" has no ERPNext equivalent, so it never shows.
  hide_name_column: true,
  filters: [["is_return", "=", 0]],
  formatters: {
    customer_name(v, df, doc) { return doc.name; },
    // Rp-prefixed like every other money column in the app (Sales Order list, forms); these were the one place showing bare numbers.
    net_total(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    grand_total(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    total_taxes_and_charges(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    custom_pph_amount(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    posting_date(v) { return "<span>" + (v ? String(v).split("-").reverse().join("/") : "") + "</span>"; },
    due_date(v, df, doc) {
      if (!v || doc.docstatus == 2 || (doc.docstatus == 1 && flt(doc.outstanding_amount) <= 0)) return "<span></span>";
      var n = Math.round((new Date(v + "T00:00:00") - new Date(new Date().toDateString())) / 864e5), t, c = "";
      if (n === 0) { t = "Today"; c = "#b7791f"; } else if (n === -1) { t = "Yesterday"; c = "#c0392b"; }
      else if (n < 0) { t = (-n) + " days ago"; c = "#c0392b"; } else if (n === 1) t = "Tomorrow"; else t = "In " + n + " days";
      return '<span style="color:' + c + '">' + t + '</span>';
    },
    outstanding_amount(v, df, doc) {
      var o = flt(doc.outstanding_amount), g = flt(doc.grand_total), t = "Not Paid", c = "red";
      if (doc.docstatus == 1) { if (o <= 0) { t = "Paid"; c = "green"; } else if (o < g) { t = "Partially Paid"; c = "orange"; } }
      return '<span class="indicator-pill ' + c + ' ellipsis"><span class="ellipsis">' + t + '</span></span>';
    }
  },

  get_indicator(doc) {
    if (doc.docstatus == 2) return ["Cancelled", "red", "docstatus,=,2"];
    if (doc.docstatus == 0) return ["Draft", "blue", "docstatus,=,0"];
    return ["Posted", "green", "docstatus,=,1"];
  },

  onload: function(listview) {

    var DATE_FIELD   = "posting_date";
    var ANCHOR_FIELD = "customer";
    var GROUP_OPTIONS = ["Year","Quarter","Month","Week","Day"];
    var selected_groups=[], collapsed_groups={}, apply_timer=null, is_rendering=false;

    if(!document.getElementById("erg-style")){
      var s=document.createElement("style");s.id="erg-style";
      s.textContent=".standard-filter-section.flex{display:flex!important;flex-wrap:wrap!important;align-items:center!important;gap:8px!important}"
        +"#erg-wrap{position:relative;flex:0 0 auto!important;min-width:1174px;max-width:160px;margin:0!important;align-self:center!important}"
        +"#erg-select{width:100%;height:28px;padding:0 28px 0 10px;border:none;border-radius:6px;background:#f3f4f6;font-size:13px;color:#36414c;display:flex;align-items:center;cursor:pointer;box-sizing:border-box}"
        +"#erg-select:hover{background:#eaecef}"
        +"#erg-text{display:block;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1}"
        +"#erg-text.is-placeholder{color:#8d99a6}"
        +"#erg-chevron{position:absolute;right:8px;top:50%;transform:translateY(-50%);pointer-events:none;color:#8d99a6;display:flex;align-items:center;z-index:2}"
        +"#erg-clr{display:none;position:absolute;right:24px;top:50%;transform:translateY(-50%);cursor:pointer;color:#8d99a6;font-size:13px;z-index:3;line-height:1}"
        +"#erg-dd{display:none;position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid #d1d8dd;border-radius:8px;min-width:1174px;z-index:9999;padding:8px 0;box-shadow:0 4px 16px rgba(0,0,0,.12)}"
        +".erg-dd-title{padding:0 12px 8px;font-size:11px;font-weight:600;color:#8d99a6;border-bottom:1px solid #f0f4f7;margin-bottom:6px}"
        +".erg-opt{display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;font-size:13px;color:#36414c}"
        +".erg-opt:hover{background:#f5f7fa}"
        +".erg-opt input{margin:0}"
        +".erg-dd-actions{display:flex;justify-content:space-between;gap:8px;padding:8px 12px 0;border-top:1px solid #f0f4f7;margin-top:6px;flex-wrap:wrap}"
        +".erg-dd-btn{flex:1;border:1px solid #d1d8dd;background:#fff;color:#36414c;font-size:11px;border-radius:6px;padding:6px 8px;cursor:pointer}"
        +".erg-dd-btn.primary{background:#2490ef;color:#fff;border-color:#2490ef}"
        +".erg-dd-btn:hover{background:#f5f7fa}"
        +".erg-dd-btn.primary:hover{background:#1a7fd4}"
        +".erg-group-separator{margin:20px 0 8px;border-top:2px solid #dbe3ea}"
        +".erg-group-header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;margin:0 0 6px;background:#f7f9fb;border:1px solid #e3e8ee;border-radius:8px;cursor:pointer;user-select:none}"
        +".erg-group-header:hover{background:#f2f6fa}"
        +".erg-group-left{display:flex;align-items:center;gap:10px;min-width:0}"
        +".erg-group-toggle{width:18px;text-align:center;color:#8d99a6;font-size:12px;flex:0 0 auto}"
        +".erg-group-title{font-size:12px;font-weight:700;color:#36414c;line-height:1.3}"
        +".erg-group-sub{font-size:11px;color:#8d99a6;line-height:1.3;margin-top:2px}"
        +".erg-group-right{display:flex;align-items:center;gap:8px;flex-shrink:0}"
        +".erg-group-count{font-size:11px;color:#68717d;background:#edf2f7;border:1px solid #dde5ee;border-radius:999px;padding:2px 8px;white-space:nowrap}"
        +".erg-group-badge{flex:0 0 auto;font-size:10px;font-weight:600;color:#68717d;background:#edf2f7;border:1px solid #dde5ee;border-radius:999px;padding:3px 8px}"
        +".erg-lvl-1{margin-top:10px}"
        +".erg-lvl-2{margin-left:18px;background:#fbfcfd}"
        +".erg-lvl-3{margin-left:36px;background:#fcfdfe}"
        +".erg-lvl-4{margin-left:54px;background:#fff}"
        +".erg-lvl-5{margin-left:72px;background:#fff}"
        +".erg-hidden-by-collapse{display:none!important}";
      document.head.appendChild(s);
    }

    var MN=["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];
    function pd(s){return s?frappe.datetime.str_to_obj(s):null}
    function wom(d){var f=new Date(d.getFullYear(),d.getMonth(),1);return Math.ceil((d.getDate()+f.getDay())/7)}
    function gv(d,mode){
      if(!d)return{key:"NO_DATE",label:"No Date"};
      var y=d.getFullYear(),m=d.getMonth(),day=d.getDate(),q=Math.floor(m/3)+1,w=wom(d);
      if(mode==="Year")    return{key:y+"",label:y+""};
      if(mode==="Quarter") return{key:y+"-Q"+q,label:"Q"+q+" "+y};
      if(mode==="Month")   return{key:y+"-"+String(m+1).padStart(2,"0"),label:MN[m]+" "+y};
      if(mode==="Week")    return{key:y+"-"+String(m+1).padStart(2,"0")+"-W"+w,label:"Minggu "+w+" - "+MN[m]+" "+y};
      if(mode==="Day")     return{key:y+"-"+String(m+1).padStart(2,"0")+"-"+String(day).padStart(2,"0"),label:String(day).padStart(2,"0")+" "+MN[m]+" "+y};
      return{key:"X",label:"Unknown"};
    }
    function esc(t){return frappe.utils.escape_html(t==null?"":String(t))}
    function getRows(){return listview.$result?listview.$result.find(".list-row-container").filter(function(){return !!getDN($(this))}):$()}
    function getDN($r){return $r.attr("data-name")||$r.find("[data-name]").first().attr("data-name")||null}
    function getDoc(n){return Array.isArray(listview.data)?listview.data.find(function(d){return d.name===n})||null:null}
    function rmv(){if(!listview.$result)return;listview.$result.find(".erg-group-header,.erg-group-separator").remove();listview.$result.find(".erg-hidden-by-collapse").removeClass("erg-hidden-by-collapse")}
    function mkSep(){return $('<div class="erg-group-separator">')}

    function mkHdr(lv,mode,label,sub,ck,count){
      var ic=!!collapsed_groups[ck];
      var countLabel=count===1?"1 transaksi":count+" transaksi";
      return $('<div class="erg-group-header erg-lvl-'+lv+'" data-group-level="'+lv+'" data-chain-key="'+esc(ck)+'" data-collapsed="'+(ic?"1":"0")+'">'
        +'<div class="erg-group-left"><div class="erg-group-toggle">'+(ic?"&#9658;":"&#9660;")+'</div>'
        +'<div class="erg-group-text"><div class="erg-group-title">'+esc(label)+'</div><div class="erg-group-sub">'+esc(sub||"")+'</div></div></div>'
        +'<div class="erg-group-right">'
        +'<div class="erg-group-count">'+esc(countLabel)+'</div>'
        +'<div class="erg-group-badge">'+esc(mode)+'</div>'
        +'</div></div>');
    }

    function doCollapse($h){
      var lv=parseInt($h.attr("data-group-level"),10);
      collapsed_groups[$h.attr("data-chain-key")]=true;
      $h.attr("data-collapsed","1").find(".erg-group-toggle").html("&#9658;");
      var $n=$h.next();
      while($n.length){if($n.hasClass("erg-group-header")&&parseInt($n.attr("data-group-level"),10)<=lv)break;$n.addClass("erg-hidden-by-collapse");$n=$n.next()}
    }
    function doExpand($h){
      var lv=parseInt($h.attr("data-group-level"),10);
      delete collapsed_groups[$h.attr("data-chain-key")];
      $h.attr("data-collapsed","0").find(".erg-group-toggle").html("&#9660;");
      var $n=$h.next();
      while($n.length){
        if($n.hasClass("erg-group-header")){
          var nl=parseInt($n.attr("data-group-level"),10);if(nl<=lv)break;
          $n.removeClass("erg-hidden-by-collapse");
          if($n.attr("data-collapsed")==="1"){var $s=$n.next();while($s.length){if($s.hasClass("erg-group-header")&&parseInt($s.attr("data-group-level"),10)<=nl)break;$s.addClass("erg-hidden-by-collapse");$s=$s.next()}}
        }else{$n.removeClass("erg-hidden-by-collapse")}
        $n=$n.next()
      }
      listview.$result.find(".erg-group-header[data-collapsed='1']").each(function(){doCollapse($(this))})
    }
    function bindEv(){listview.$result.find(".erg-group-header").off("click.erg").on("click.erg",function(e){e.stopPropagation();$(this).attr("data-collapsed")==="1"?doExpand($(this)):doCollapse($(this))})}

    function applyGrouping(){
      if(is_rendering||!listview.$result)return;
      if(!selected_groups.length){rmv();return}
      is_rendering=true;
      try{
        rmv();
        var rs=[];
        getRows().each(function(){var $r=$(this),n=getDN($r);if(!n)return;var d=getDoc(n),dv=d?d[DATE_FIELD]:null,dObj=pd(dv);rs.push({$r:$r,n:n,dObj:dObj,ts:dObj?dObj.getTime():0})});
        rs.sort(function(a,b){return a.ts!==b.ts?a.ts-b.ts:a.n.localeCompare(b.n)});
        if(rs.length){var $p=rs[0].$r.parent();rs.forEach(function(r){$p.append(r.$r)})}

        // Hitung count per chainKey
        var countMap={};
        rs.forEach(function(item){
          var chain=selected_groups.map(function(mode){var g=gv(item.dObj,mode);return{mode:mode,key:String(g.key),label:g.label}});
          chain.forEach(function(g,idx){
            var ck=chain.slice(0,idx+1).map(function(x){return x.mode+":"+x.key}).join("||");
            countMap[ck]=(countMap[ck]||0)+1;
          });
        });

        var pk=[],pt=null;
        rs.forEach(function(item){
          var chain=selected_groups.map(function(mode){var g=gv(item.dObj,mode);return{mode:mode,key:String(g.key),label:g.label}});
          if(!chain.length)return;
          var tk=chain[0].mode+":"+chain[0].key;
          chain.forEach(function(g,idx){
            var lv=idx+1,ck=chain.slice(0,lv).map(function(x){return x.mode+":"+x.key}).join("||");
            if(pk[idx]!==ck){
              if(idx===0&&pt!==null&&tk!==pt)item.$r.before(mkSep());
              var sub=idx===0?"Group by "+g.mode:chain.slice(0,idx).map(function(x){return x.label}).join(" / ");
              var count=countMap[ck]||0;
              item.$r.before(mkHdr(lv,g.mode,g.label,sub,ck,count));
              pk[idx]=ck;for(var j=idx+1;j<pk.length;j++)pk[j]=null
            }
          });
          pt=tk
        });
        bindEv();
        if(!Object.keys(collapsed_groups).length)listview.$result.find(".erg-group-header").each(function(){doCollapse($(this))});
        else listview.$result.find(".erg-group-header[data-collapsed='1']").each(function(){doCollapse($(this))})
      }finally{is_rendering=false}
    }

    function sched(d){clearTimeout(apply_timer);apply_timer=setTimeout(applyGrouping,d||400)}
    function updDisp(){
      if(selected_groups.length){$("#erg-text").text(selected_groups.join(" + ")).removeClass("is-placeholder");$("#erg-clr").show()}
      else{$("#erg-text").text("Group By").addClass("is-placeholder");$("#erg-clr").hide()}
    }
    function syncChk(){$("#erg-dd .erg-opt-check").each(function(){$(this).prop("checked",selected_groups.indexOf($(this).val())>-1)})}
    function buildUI(){
      var opts=GROUP_OPTIONS.map(function(o){return'<label class="erg-opt"><input type="checkbox" class="erg-opt-check" value="'+o+'"><span>'+o+'</span></label>'}).join("");
      return $('<div id="erg-wrap">'
        +'<div id="erg-select"><span id="erg-text" class="is-placeholder">Group By</span></div>'
        +'<div id="erg-chevron"><svg class="icon icon-xs" aria-hidden="true"><use href="#icon-select"></use></svg></div>'
        +'<span id="erg-clr">&times;</span>'
        +'<div id="erg-dd"><div class="erg-dd-title">Pilih level grouping</div>'+opts
        +'<div class="erg-dd-actions">'
        +'<button class="erg-dd-btn" id="erg-sa">All</button>'
        +'<button class="erg-dd-btn" id="erg-ca">Clear</button>'
        +'<button class="erg-dd-btn primary" id="erg-ap">Apply</button>'
        +'</div></div></div>');
    }
    function attachUI($w){
      $w.on("click","#erg-select",function(e){e.stopPropagation();syncChk();$("#erg-dd").toggle()});
      $w.on("click","#erg-sa",function(e){e.stopPropagation();$("#erg-dd .erg-opt-check").prop("checked",true)});
      $w.on("click","#erg-ca",function(e){e.stopPropagation();$("#erg-dd .erg-opt-check").prop("checked",false)});
      $w.on("click","#erg-ap",function(e){
        e.stopPropagation();
        selected_groups=GROUP_OPTIONS.filter(function(o){return $("#erg-dd .erg-opt-check[value='"+o+"']").prop("checked")});
        collapsed_groups={};updDisp();$("#erg-dd").hide();sched(300)
      });
      $w.on("click","#erg-clr",function(e){e.stopPropagation();selected_groups=[];collapsed_groups={};updDisp();rmv();syncChk()});
      $(document).off("click.erg").on("click.erg",function(){$("#erg-dd").hide()});
      $w.on("click","#erg-dd",function(e){e.stopPropagation()})
    }
    function injectUI(){
      $("#erg-wrap").remove();
      var $a=$('[data-fieldname="'+ANCHOR_FIELD+'"].frappe-control');
      if(!$a.length)return false;
      var $w=buildUI();$a.after($w);attachUI($w);updDisp();return true
    }
    if(!listview.__erg_patched){
      listview.__erg_patched=true;
      var oR=listview.render,oRf=listview.refresh;
      listview.render=function(){var r=oR.apply(this,arguments);sched(500);return r};
      listview.refresh=function(){var r=oRf.apply(this,arguments);sched(600);return r}
    }
    frappe.after_ajax(function(){
      if(!injectUI()){var n=0;var iv=setInterval(function(){n++;if(injectUI()||n>20)clearInterval(iv)},200)}
      sched(700)
    })
  }
};

/* si-list-style */
// Tag column is empty for every row, so it is collapsed.
// Same look as the Sales Order list: blue header, centered titles, numbers right-aligned, "Number" label.
// ponytail: nth-child ties widths to column order (1 Number, 2 Tag, 3 Customer, 4 Invoice Date, 5 Due Date, 6 Tax Number, 7 Tax Excluded, 8 Total, 9 Payment Status, 10 Total PPN, 11 Total PPh, 12 Status). Update if columns move.
// si-no-dup-currency: "Total in Currency" (base_grand_total) dropped - this shop is IDR-only (one Company,
// no multi-currency sales), so it was always identical to Total and just ate space the user has to scroll for.
// si-order-fix: imogi_finance's global custom.css sets `order` on .list-row-col:nth-child(2..7) for every
// list view site-wide (no page scoping), which visually scrambles column order here (Total/Payment Status
// jump before Customer/Invoice Date). `[data-page-route=...] .frappe-list .list-row-head .level-left >` has
// higher specificity than imogi's bare `.list-row-head .list-row-col`, so resetting order here wins without
// touching that other app's file.
(function(){
  if (document.getElementById("si-list-style")) return;
  var P = '[data-page-route="List/Sales Invoice/List"] ', R = P + '.frappe-list ', st = document.createElement("style"); st.id = "si-list-style";
  // 7/8/9/11/12 (money columns) widened to fit the "Rp " prefix - at the old widths the flex-end+overflow:hidden
  // combo clipped the left edge of the text instead of the right, so "Rp 150.000,00" rendered as "p 150.000,00".
  var W = {1:'1 0 194px',2:'0 0 0px',3:'3 0 120px',4:'1 0 80px',5:'1 0 84px',6:'1 0 122px',7:'1 0 110px',8:'1 0 110px',9:'1 0 114px',10:'1 0 100px',11:'1 0 95px',12:'1 0 84px'}, css = '';
  Object.keys(W).forEach(function(i){ ['.list-row-container .list-row','.list-row-head'].forEach(function(r){ css += R + r + ' .level-left > .list-row-col:nth-child('+i+'){flex:'+W[i]+' !important;min-width:0 !important;width:auto !important;order:'+i+' !important}'; }); });
  css += P + '.list-row-head,' + P + '.list-row-head .list-row-col,' + P + '.list-row-head .list-subject,' + P + '.list-row-head .level-item,' + P + '.list-row-head .level-right{background-color:#dbe4ef !important}';
  css += P + '.list-row-head{min-height:40px !important;align-items:center !important}';
  css += R + '.list-row-container .list-row .list-subject a{font-weight:600 !important;color:#36414c !important}';
  css += R + '.list-row-container .list-row > .level-right, ' + R + '.list-row-head > .level-right{display:none !important}';
  css += R + '.list-row-container .list-row > .level-left, ' + R + '.list-row-head > .level-left{flex:1 1 auto !important;width:100% !important}';
  css += R + '.list-row-head .list-row-col{white-space:normal !important;overflow:visible !important;text-overflow:clip !important;line-height:1.25;font-size:12px}';
  css += R + '.list-row-container .list-row .list-row-col{font-size:13px}';
  css += R + '.level-left > .list-row-col:nth-child(2){display:none !important}' + R + '.level-left{align-items:stretch !important}' + R + '.level-left > .list-row-col:not(.hide){display:flex !important;align-items:center}';
  css += R + '.list-row-head .level-left > .list-row-col:not(.list-subject){justify-content:center !important;text-align:center !important}';
  css += R + '.list-row-head .list-subject .level-item:not(.select-like){flex:1 1 auto !important;text-align:center !important}';
  css += R + '.list-row-head .list-subject, ' + R + '.list-row-head .list-subject .list-header-subject{justify-content:flex-start !important}';
  [7,8,10,11].forEach(function(i){ ['.list-row-container .list-row','.list-row-head'].forEach(function(r){ css += R + r + ' .level-left > .list-row-col:nth-child('+i+'){justify-content:flex-end !important;text-align:right}'; }); });
  [4,5,9,12].forEach(function(i){ css += R + '.list-row-container .list-row .level-left > .list-row-col:nth-child('+i+'){justify-content:center !important;text-align:center !important}'; });
  // ponytail: 12 fixed-width columns (sum ~1213px, grow so the row fills the width) do not fit beside the desk sidebar at 1280/1440; the list scrolls sideways inside its own box. Shrink widths if Number or Customer text is cut.
  css += R + '.list-row-head,' + R + '.list-row-container .list-row{min-width:1213px}' + R + '.list-row-col{margin-right:0 !important;padding-right:6px !important;box-sizing:border-box}' + R + '.result{overflow-x:auto}';
