      function mkHdr(lv, mode, label, sub, ck, count, sum) {
        var ic = !!collapsed_groups[ck];
        var countLabel = count === 1 ? "1 transaksi" : count + " transaksi";
        var sumLabel = typeof format_currency === "function" ? format_currency(sum || 0) : (sum || 0);
        return $('<div class="ob-erg-group-header ob-erg-lvl-' + lv + '" data-group-level="' + lv + '" data-chain-key="' + esc(ck) + '" data-collapsed="' + (ic ? "1" : "0") + '">'
          + '<div class="ob-erg-group-left"><div class="ob-erg-group-toggle">' + (ic ? "&#9658;" : "&#9660;") + '</div>'
          + '<div class="ob-erg-group-text"><div class="ob-erg-group-title">' + esc(label) + '</div><div class="ob-erg-group-sub">' + esc(sub || "") + '</div></div></div>'
