            if ($n.attr("data-collapsed") === "1") { var $sb = $n.next(); while ($sb.length) { if ($sb.hasClass("ob-erg-group-header") && parseInt($sb.attr("data-group-level"), 10) <= nl) break; $sb.addClass("ob-erg-hidden-by-collapse"); $sb = $sb.next(); } }
          } else { $n.removeClass("ob-erg-hidden-by-collapse"); }
          $n = $n.next();
