          + '<div id="ob-erg-select"><span id="ob-erg-text" class="is-placeholder">Group By</span></div>'
          + '<div id="ob-erg-chevron"><svg class="icon icon-xs" aria-hidden="true"><use href="#icon-select"></use></svg></div>'
          + '<span id="ob-erg-clr">&times;</span>'
          + '<div id="ob-erg-dd"><div class="ob-erg-dd-title">Pilih level grouping</div>' + opts
          + '<div class="ob-erg-dd-actions">'
          + '<button class="ob-erg-dd-btn" id="ob-erg-sa">All</button>'
          + '<button class="ob-erg-dd-btn" id="ob-erg-ca">Clear</button>'
          + '<button class="ob-erg-dd-btn primary" id="ob-erg-ap">Apply</button>'
          + '</div></div></div>');
      }
      function attachUI($w) {
        $w.on("click", "#ob-erg-select", function (e) { e.stopPropagation(); syncChk(); $w.find("#ob-erg-dd").toggle(); });
        $w.on("click", "#ob-erg-sa", function (e) { e.stopPropagation(); $w.find(".ob-erg-opt-check").prop("checked", true); });
        $w.on("click", "#ob-erg-ca", function (e) { e.stopPropagation(); $w.find(".ob-erg-opt-check").prop("checked", false); });
        $w.on("click", "#ob-erg-ap", function (e) {
