/* so-number-head */
// Odoo calls the first list column "Number". Frappe hardcodes "ID" for it; rename in DOM after each render.
// ponytail: MutationObserver on list header only; remove if Frappe adds a label option.
(function(){
  const fix = () => document.querySelectorAll('[data-page-route="List/Sales Order/List"] .list-row-head .list-subject .list-header-subject span, [data-page-route="List/Sales Order/List"] .list-row-head .list-subject span.level-item:not(.select-like)').forEach(e => { if (e.children.length === 0 && e.textContent.trim() === 'ID') e.textContent = 'Number'; });
  new MutationObserver(fix).observe(document.body, {childList: true, subtree: true});
})();

/* so-col-widths */
// Fixed widths for short/code columns, flex (grow) for text columns.
// Keyed by data-fieldname (set by Frappe on every .list-row-col), not column position:
// nth-child broke the moment List View Settings' field order changed (that's what
// squeezed Customer in the screenshot this was reported from) - fieldname is stable
// across reordering, drag-resize, and hidden/shown columns.
(function(){
  if (document.getElementById("so-col-widths")) return;
  var R = '[data-page-route="List/Sales Order/List"] .frappe-list ', st = document.createElement("style"); st.id = "so-col-widths";
  // flex-grow, flex-basis per field. customer_name grows the most: it's the field users scan first and most often truncated.
  var W = {
    customer_name: '3 0 180px',
    custom_salesperson: '1 0 110px',
    transaction_date: '0 0 98px',
    custom_payment_status: '0 0 130px',
    custom_otobitz_so_number: '1 0 110px',
    custom_otobitz_faktur_number: '1 0 110px',
    company: '1 0 150px',
    grand_total: '0 0 124px'
  };
  var CENTERED = ['transaction_date', 'custom_payment_status'];
  var WRAP = ['customer_name', 'custom_salesperson', 'company', 'custom_otobitz_so_number', 'custom_otobitz_faktur_number'];
  var css = '';
  Object.keys(W).forEach(function(f){
    ['.list-row-container .list-row', '.list-row-head'].forEach(function(r){
      css += R + r + ' .level-left > .list-row-col[data-fieldname="'+f+'"]{flex:'+W[f]+' !important;min-width:0 !important;width:auto !important}';
    });
  });
  // Number column (Subject): fixed width regardless of fieldname (its fieldname varies: name or title_field)
  css += R + '.list-row-container .list-row .list-subject.level, '+R+'.list-row-head .list-subject.level{flex:0 0 190px !important;min-width:0 !important;width:auto !important}';
  css += R + '.list-row-container .list-row .list-subject a{font-weight:600 !important;color:#36414c !important}';
  css += R + '.list-row-container .list-row .level-left > .list-row-col[data-fieldname="grand_total"]{justify-content:flex-end;text-align:right}';
  css += R + '.list-row-head .level-left > .list-row-col[data-fieldname="grand_total"]{justify-content:flex-end;text-align:right}';
  css += R + '.list-row-container .list-row .level-left > .list-row-col{padding-right:4px}';
  // hide modified-time/like area on the right: Odoo list has none, and it steals 130px
  css += R + '.list-row-container .list-row > .level-right, '+R+'.list-row-head > .level-right{display:none !important}';
  css += R + '.list-row-container .list-row > .level-left, '+R+'.list-row-head > .level-left{flex:1 1 auto !important;width:100% !important}';
  // header may wrap to 2 lines instead of being cut; body cells stay single-line with ellipsis
  css += R + '.list-row-head .list-row-col{white-space:normal !important;overflow:visible !important;text-overflow:clip !important;line-height:1.25;font-size:12px}';
  css += R + '.list-row-container .list-row .list-row-col{font-size:13px}';
  /* so-head-num */ css += R + '.list-row-head .list-subject .level-item:not(.select-like){flex:1 1 auto !important;text-align:center !important}';
  /* so-head-center */
  css += R + '.list-row-head .level-left > .list-row-col:not(.list-subject){justify-content:center !important;text-align:center !important}';
  css += R + '.list-row-head .list-subject .list-header-subject, '+R+'.list-row-head .list-subject{justify-content:flex-start !important}';
  // body cells under centered headers: Order Date, Invoice Status centered; Total stays right-aligned like Odoo
  CENTERED.forEach(function(f){
    css += R + '.list-row-container .list-row .level-left > .list-row-col[data-fieldname="'+f+'"]{justify-content:center !important;text-align:center !important}';
  });
  // ponytail: min-width = sum of column bases (~1230px); narrower windows scroll inside the list instead of cutting text. Update if widths change.
  css += R + '.list-row-container .list-row, '+R+'.list-row-head{min-width:1176px !important}';
  css += R + '.result{overflow-x:auto}';
  // text columns wrap to a second line instead of being cut
  WRAP.forEach(function(f){
    var c = R+'.list-row-container .list-row .level-left > .list-row-col[data-fieldname="'+f+'"]';
    css += c+' .ellipsis, '+c+' a, '+c+', '+c+' span{white-space:normal !important;overflow:visible !important;text-overflow:clip !important;overflow-wrap:anywhere;line-height:1.25}';
  });
  css += R + '.list-row-container .list-row{min-height:40px}';
  // ponytail: Frappe adds 15px margin per column; zero it so column bases are the real widths.
  css += R + '.list-row-col{margin-right:0 !important;padding-right:6px !important;box-sizing:border-box}';
  st.textContent = css; document.head.appendChild(st);
})();

