        frm.set_value('custom_tahun_kendaraan', r.tahunpembuatan || '');
        frm.set_value('custom_vehicle_type', r.vehicle_type || '');
        frm.set_value('custom_warna', r.vehicle_color || '');
        if (r.last_odometer) frm.set_value('custom_odometer', r.last_odometer);
