        if (r.vehicle_type) frappe.db.get_value('OtoBitz Vehicle Type', r.vehicle_type, ['brand','transmisi','custom_model'], t => { frm.set_value('custom_vehicle_manufacture', (t && t.brand) || ''); frm.set_value('custom_transmisi', (t && t.transmisi) || ''); frm.set_value('custom_vehicle_model', (t && t.custom_model) || ''); });
