// Discount: Fixed / Percentage (Odoo style)
function so_apply_discount(frm, cdt, cdn) {
  const r = locals[cdt][cdn];
  const v = flt(r.custom_discount_value);
  const pct = (r.custom_discount_type === 'Percentage');
  r[pct ? 'discount_amount' : 'discount_percentage'] = 0;
  r[pct ? 'discount_percentage' : 'discount_amount'] = v;
  frm.script_manager.trigger(pct ? 'discount_percentage' : 'discount_amount', cdt, cdn);
  frm.refresh_field('items');
}
frappe.ui.form.on('Sales Order Item', {
  custom_discount_type(frm, cdt, cdn) { so_apply_discount(frm, cdt, cdn); },
  custom_discount_value(frm, cdt, cdn) { so_apply_discount(frm, cdt, cdn); },
  items_add(frm, cdt, cdn) { frappe.model.set_value(cdt, cdn, 'custom_discount_type', 'Fixed'); }
});


