/* si-tax-dd */
// ponytail: display-only. Shortens the Tax dropdown rows ("(Inc) Pajak Pertambahan Nilai - PAO" -> "PPN Inc"). Awesomplete selects by its own data, not DOM text, so the saved value stays the full template name. Matches on the tax name text, so a new tax template needs its own rule.
(function () {
  if (window.__tax_dd) return; window.__tax_dd = 1;
  const short = t => t.replace(/\s-\s[A-Z]{2,5}$/, '').replace('(Inc) Pajak Pertambahan Nilai', 'PPN Inc').replace('(Excl) Pajak Pertambahan Nilai', 'PPN Excl');
  new MutationObserver(() => {
    document.querySelectorAll('.awesomplete ul p[title*="Pajak Pertambahan Nilai"]:not([data-short])').forEach(p => {
      p.dataset.short = 1;
      const s = p.querySelector('strong'); if (s) s.textContent = short(s.textContent);
      const sm = p.querySelector('.small'); if (sm) { sm.remove(); const br = p.querySelector('br'); br && br.remove(); }
    });
  }).observe(document.body, { childList: true, subtree: true });
})();

/* so-tax-short */
// ponytail: display-only. Grid cell shows "PPN Inc"/"PPN Excl" instead of the full template name; saved value unchanged. A new tax template needs its own rule.
(function () {
  const F = frappe.form.formatters;
  if (!F.Link || F.Link.__so_tax) return;
  const o = F.Link;
  F.Link = function (v, df) {
    const out = o.apply(this, arguments);
    if (df && df.parent === 'Sales Order Item' && df.fieldname === 'item_tax_template' && typeof out === 'string')
      return out.replace(/>([^<]+)</g, (m, t) => '>' + t.replace(/\s-\s[A-Z]{2,5}$/, '').replace('(Inc) Pajak Pertambahan Nilai', 'PPN Inc').replace('(Excl) Pajak Pertambahan Nilai', 'PPN Excl') + '<');
    return out;
  };
  F.Link.__so_tax = 1;
  frappe.ui.form.on('Sales Order', { refresh(frm) { frm.fields_dict.items && frm.fields_dict.items.grid.refresh(); } });
})();

